windows_cml_clear:
     movq    %rcx, %r9
     movq    %rdx, %r8
     movq    %rsi, %rdx
     movq    %rdi, %rcx
     jmp     cdecl(cml_clear)
cml_enter:
     sub     $0x30, %rsp
     movq    %r12, -0x8(%rbp)
     movq    %r13, -0x10(%rbp)
     movq    %r14, -0x18(%rbp)
     movq    %r15, -0x20(%rbp)
     movq    %rbx, -0x28(%rbp)
     jmp     cake_main

windows_cake_enter:
     movq    %rcx, %rdi
     movq    %rdx, %rsi
     movq    %r8, %rdx
     movq    %r9, %rcx

cake_enter:
     pushq   %rbp
     movq    %rsp, %rbp
     sub     $0x30, %rsp
     movq    %r12, -0x8(%rbp)
     movq    %r13, -0x10(%rbp)
     movq    %r14, -0x18(%rbp)
     movq    %r15, -0x20(%rbp)
     movq    %rbx, -0x28(%rbp)
     movq    can_enter(%rip), %r11
     cmp     $0, %r11
     je      cake_err3
     movq    $0, can_enter(%rip)
     movq    ret_base(%rip), %r14
     movq    ret_stack(%rip), %r12
     movq    ret_stackend(%rip), %r13
     lea     cake_return(%rip), %rax
     jmp     *%r10
     .p2align 4

cml_return:
     movq    %r14, ret_base(%rip)
     movq    %r12, ret_stack(%rip)
     movq    %r13, ret_stackend(%rip)

cake_return:
     movq    $1, can_enter(%rip)
     mov     %edi, %eax
     movq    -0x28(%rbp),%rbx
     movq    -0x20(%rbp),%r15
     movq    -0x18(%rbp),%r14
     movq    -0x10(%rbp),%r13
     movq    -0x8(%rbp),%r12
     leave
     ret
     .p2align 4

cake_err3:
     pushq   %rax
     movq    $3, %rdi
     jmp     wcdecl(cml_err)
     .p2align 4

windows_cml_err:
     movq    %rcx, %r9
     movq    %rdx, %r8
     movq    %rsi, %rdx
     movq    %rdi, %rcx
     jmp     cdecl(cml_err)

